INSERT INTO sources (id, url, title, organization, source_type, academic_year, publication_date, excerpt, verification_status) VALUES
('a0000001-0000-0000-0000-000000000001', 'https://testcenter.kz/', 'Ұлттық тестілеу орталығының ресми ережелері', 'ҚР ҒЖБМ ҰТО', 'authority', '2026-2027', '2026-01-15', 'ҰБТ шекті балдары: Ұлттық ЖОО - кемінде 65 балл, Педагогика және медицина - 75 балл, Өзге ЖОО - 50 балл.', 'verified'),
('a0000001-0000-0000-0000-000000000002', 'https://www.gov.kz/memleket/entities/astana-bilim', 'Астана қаласы Білім басқармасының мемлекеттік білім беру тапсырысы (303 грант)', 'Астана қаласы Білім басқармасы', 'authority', '2026-2027', '2026-06-01', 'Астана қаласы әкімінің 303 гранты қалаға аса қажетті мамандарды даярлау үшін бөлінеді (педагогика, медицина, көлік қызметі, IT). Тамыздың 5-10 аралығында ЖОО қабылдау комиссияларында.', 'verified'),
('a0000001-0000-0000-0000-000000000003', 'https://astanait.edu.kz/', 'Astana IT University ресми қабылдау ережелері', 'Astana IT University', 'institution_official', '2026-2027', '2026-02-10', 'AITU қабылдау шекті балы: кемінде 65 балл (Математика + Информатика комбинациясы). Ректор гранттары олимпиада жүлдегерлеріне беріледі.', 'verified'),
('a0000001-0000-0000-0000-000000000004', 'https://enu.kz/', 'Л.Н. Гумилев атындағы ЕҰУ қабылдау комиссиясы', 'Л.Н. Гумилев атындағы ЕҰУ', 'institution_official', '2026-2027', '2026-02-01', 'Ұлттық университет мәртебесі бойынша ең төменгі шекті балл - 65. Педагогикалық бағыттар үшін - 75 балл.', 'verified'),
('a0000001-0000-0000-0000-000000000005', 'https://amu.edu.kz/', 'Астана медицина университетінің талапкерлер бөлімі', 'Астана медицина университеті', 'institution_official', '2026-2027', '2026-01-20', 'Денсаулық сақтау бағытында шекті балл кемінде 70. Міндетті түрде психометриялық емтихан тапсырылады.', 'verified'),
('a0000001-0000-0000-0000-000000000006', 'https://polytech.kz/', 'Астана политехникалық колледжінің қабылдау ережелері', 'Астана политехникалық колледжі', 'institution_official', '2026-2027', '2026-05-10', '9 және 11-сыныптан кейін мемлекеттік тапсырыс бойынша қабылдау аттестаттың орташа конкурстық балы бойынша өтеді. ҰБТ талап етілмейді.', 'verified'),
('a0000001-0000-0000-0000-000000000007', 'https://qazaqstanhalqyna.kz/', '"Қазақстан халқына" қорының білім беру гранттары', '"Қазақстан халқына" ҚҚ', 'authority', '2026-2027', '2026-06-15', 'Әлеуметтік осал санаттағы талапкерлер мен ауыл жастарына мемлекеттік грант алмаған жағдайда толық оқу ақысы және шәкіртақы төленеді.', 'verified'),
('a0000001-0000-0000-0000-000000000008', 'https://astanahub.com/en/tech-orda/', 'Tech Orda ваучерлік IT бағдарламасы', 'Astana Hub', 'authority', '2026-2027', '2026-03-01', 'Қазақстан азаматтары үшін жетекші IT мектептерде 600 000 теңгеге дейін тегін білім беру ваучері.', 'verified'),
('a0000001-0000-0000-0000-000000000009', '/docs/ForteBank_RU_print_compact.pdf', 'ForteBank Абитуриент жолсілтемесі 2025 (Путеводитель абитуриента)', 'ForteBank & Bilim Foundation', 'authority', '2025-2026', '2025-06-01', 'Астана ЖОО қабылдау квоталары (10 санат, ҚР ҒЖБМ №357/261 бұйрықтары), 2025 жылғы нақты өту баллдары, әкімдіктің 303 гранты, бос грантқа ауысу регламенті (GPA).', 'verified'),
('a0000001-0000-0000-0000-000000000010', 'https://kazenergy.com', 'KAZENERGY білім беру гранттық бағдарламасы', 'KAZENERGY / NCOC / Karachaganak Petroleum Operating', 'authority', '2026-2027', '2026-04-01', 'NCOC және KPO қаржыландыруымен техникалық, IT және мұнай-газ саласы студенттеріне толық 100% оқу ақысын төлеу.', 'verified'),
('a0000001-0000-0000-0000-000000000011', 'https://alem.school', 'Tomorrow School (alem.ai) Жасанды интеллект және IT мектебі', 'Astana Hub / Tomorrow School', 'institution_official', '2026-2027', '2026-03-01', 'Астанадағы мұғалімсіз және дәріссіз peer-to-peer бағдарламалау мектебі (Go, Rust, JS, AI). 100% тегін оқу.', 'verified'),
('a0000001-0000-0000-0000-000000000012', 'https://joltap.kz', 'JOLTAP Астана қаласы тұрғындарының цифрлық дағдылары жобасы', 'Астана қаласының әкімдігі', 'authority', '2026-2027', '2026-01-10', 'Астана тұрғындарына арналған қысқа мерзімді тегін модульдік курстар (SMM, таргетинг, график-дизайн, веб-сайт, жұмысшы дағдылар).', 'verified'),
('a0000001-0000-0000-0000-000000000013', 'https://kazguu.kz', 'Maqsut Narikbayev University ресми қабылдау ережелері', 'Maqsut Narikbayev University (MNU)', 'institution_official', '2026-2027', '2026-02-15', 'Құқық (B042), халықаралық құқық, экономика және IT бағдарламалары. 2025 ж. ҰБТ өту балы: 125.', 'verified'),
('a0000001-0000-0000-0000-000000000014', 'https://aiu.edu.kz', 'Astana International University қабылдау ережелері', 'Astana International University (AIU)', 'institution_official', '2026-2027', '2026-02-10', 'Педагогикалық бағыттар, IT және дизайн. Астана әкімі гранттарының негізгі серіктес ЖОО бірі.', 'verified'),
('a0000001-0000-0000-0000-000000000015', 'https://studenthub.kz', 'StudentHub.kz Қазақстанның білім беру платформасы', 'StudentHub.kz', 'authority', '2026-2027', '2026-02-01', 'Қазақстан ЖОО-ларының білім беру бағдарламалары, ҰБТ шекті және өту баллдары, орташа оқу ақысы және абитуриенттер базасы.', 'verified');
