INSERT INTO institution_programs (id, institution_id, program_group_id, program_id, education_level, study_languages, tuition_fee_kzt, tuition_period, is_available, admission_info_kz, admission_info_ru, status, source_id) VALUES
('f0000001-0000-0000-0000-000000000001', 'd0000001-0000-0000-0000-000000000001', 'e0000001-0000-0000-0000-000000000002', 'e1000001-0000-0000-0000-000000000001', 'bachelor', '{"KZ", "RU", "EN"}', 1250000.00, 'per_year', true, 'AITU қабылдау үшін ҰБТ кемінде 65 балл болуы шарт. Ағылшын тілі деңгейі тексеріледі.', 'Для поступления в AITU требуется минимум 65 баллов ЕНТ. Английский язык является языком части дисциплин.', 'verified', 'a0000001-0000-0000-0000-000000000003'),
('f0000001-0000-0000-0000-000000000002', 'd0000001-0000-0000-0000-000000000001', 'e0000001-0000-0000-0000-000000000001', 'e1000001-0000-0000-0000-000000000003', 'bachelor', '{"KZ", "RU", "EN"}', 1250000.00, 'per_year', true, 'AITU Киберқауіпсіздік бағдарламасына мемлекеттік гранттар және ректор гранттары беріледі.', 'На программу Кибербезопасность выделяются государственные и ректорские гранты.', 'verified', 'a0000001-0000-0000-0000-000000000003'),
('f0000001-0000-0000-0000-000000000003', 'd0000001-0000-0000-0000-000000000002', 'e0000001-0000-0000-0000-000000000002', 'e1000001-0000-0000-0000-000000000002', 'bachelor', '{"KZ", "RU"}', 1100000.00, 'per_year', true, 'ЕҰУ ұлттық мәртебеге ие болғандықтан, шекті балл - 65.', 'Поскольку ЕНУ национальный вуз, минимальный пороговый балл равен 65.', 'verified', 'a0000001-0000-0000-0000-000000000004'),
('f0000001-0000-0000-0000-000000000004', 'd0000001-0000-0000-0000-000000000003', 'e0000001-0000-0000-0000-000000000003', 'e1000001-0000-0000-0000-000000000004', 'bachelor', '{"KZ", "RU"}', 1350000.00, 'per_year', true, 'ҰБТ шекті балы кемінде 70. Психометриялық емтиханнан өту міндетті.', 'Пороговый балл не менее 70. Обязательна сдача психометрического тестирования.', 'verified', 'a0000001-0000-0000-0000-000000000005'),
('f0000001-0000-0000-0000-000000000005', 'd0000001-0000-0000-0000-000000000004', 'e0000001-0000-0000-0000-000000000006', 'e1000001-0000-0000-0000-000000000005', 'college', '{"KZ", "RU"}', 0.00, 'per_year', true, 'Астана қаласы бойынша тегін мемлекеттік білім беру тапсырысы (грант) қарастырылған. Аттестат конкурсы.', 'Предусмотрен бесплатный государственный образовательный заказ г. Астана. Конкурс аттестатов.', 'verified', 'a0000001-0000-0000-0000-000000000006'),
('f0000001-0000-0000-0000-000000000006', 'd0000001-0000-0000-0000-000000000006', 'e0000001-0000-0000-0000-000000000004', 'e1000001-0000-0000-0000-000000000006', 'bachelor', '{"KZ", "RU", "EN"}', 1400000.00, 'per_year', true, 'MNU Құқықтану бағдарламасына ҰБТ шекті балы - 75. 2025 жылғы мемлекеттік гранттың өту балы 125 болды.', 'Минимальный порог ЕНТ в MNU - 75 баллов. Проходной балл на госгрант в 2025 году составил 125 баллов.', 'verified', 'a0000001-0000-0000-0000-000000000013'),
('f0000001-0000-0000-0000-000000000007', 'd0000001-0000-0000-0000-000000000007', 'e0000001-0000-0000-0000-000000000007', 'e1000001-0000-0000-0000-000000000007', 'bachelor', '{"KZ", "RU"}', 950000.00, 'per_year', true, 'Педагогикалық бағытқа шекті балл - 75. Астана әкімінің 303 грантына құжат тапсыруға болады.', 'Порог на педагогику - 75 баллов. Доступна подача на целевые гранты акима Астаны.', 'verified', 'a0000001-0000-0000-0000-000000000014'),
('f0000001-0000-0000-0000-000000000008', 'd0000001-0000-0000-0000-000000000012', 'e0000001-0000-0000-0000-000000000008', 'e1000001-0000-0000-0000-000000000008', 'bachelor', '{"KZ", "RU"}', 780000.00, 'per_year', true, 'Туран-Астана университетінің Менеджмент бағдарламасы. Ректорлық ішкі жеңілдіктер бар.', 'Программа Менеджмента в университете Туран-Астана. Внутренние гранты и скидки до 50%.', 'verified', 'a0000001-0000-0000-0000-000000000015'),
('f0000001-0000-0000-0000-000000000009', 'd0000001-0000-0000-0000-000000000012', 'e0000001-0000-0000-0000-000000000009', 'e1000001-0000-0000-0000-000000000009', 'bachelor', '{"KZ", "RU"}', 780000.00, 'per_year', true, 'Қаржы және аудит. ҰБТ шекті балы - 50. Студенттер үйі мен әскери кафедра бар.', 'Финансы и аудит. Порог ЕНТ - 50 баллов. Военная кафедра и общежитие.', 'verified', 'a0000001-0000-0000-0000-000000000015'),
('f0000001-0000-0000-0000-000000000010', 'd0000001-0000-0000-0000-000000000006', 'e0000001-0000-0000-0000-000000000009', 'e1000001-0000-0000-0000-000000000009', 'bachelor', '{"KZ", "RU", "EN"}', 1350000.00, 'per_year', true, 'MNU Қаржы және аналитика бағдарламасы. АХҚО (AIFC) аккредитациясы.', 'Программа Финансов и аналитики MNU с аккредитацией МФЦА.', 'verified', 'a0000001-0000-0000-0000-000000000013'),
('f0000001-0000-0000-0000-000000000011', 'd0000001-0000-0000-0000-000000000001', 'e0000001-0000-0000-0000-000000000010', 'e1000001-0000-0000-0000-000000000010', 'bachelor', '{"KZ", "RU", "EN"}', 1250000.00, 'per_year', true, 'Телекоммуникациялар және желілер. Шекті балл - 65.', 'Телекоммуникации и сети связи в AITU. Порог - 65 баллов.', 'verified', 'a0000001-0000-0000-0000-000000000003'),
('f0000001-0000-0000-0000-000000000012', 'd0000001-0000-0000-0000-000000000011', 'e0000001-0000-0000-0000-000000000002', 'e1000001-0000-0000-0000-000000000001', 'bachelor', '{"EN"}', 0.00, 'per_year', true, 'NUET / SAT + IELTS арқылы қабылдау (ҰБТ есептелмейді). Толық 100% грант беріледі.', 'Поступление по NUET или SAT + IELTS (без ЕНТ). 100% грант Назарбаев Университета.', 'verified', 'a0000001-0000-0000-0000-000000000015');
INSERT INTO admission_requirements (id, academic_year, program_group_id, institution_id, profile_subject_1_kz, profile_subject_1_ru, profile_subject_2_kz, profile_subject_2_ru, min_unt_total_score, institution_specific_threshold, creative_exam_required, eligibility_rules_kz, eligibility_rules_ru, status, source_id) VALUES
('10000001-0000-0000-0000-000000000001', '2026-2027', 'e0000001-0000-0000-0000-000000000001', NULL, 'Математика', 'Математика', 'Информатика', 'Информатика', 50, 65, false, 'Ұлттық ЖОО үшін шекті балл - 65, жалпы ЖОО үшін - 50. Әр пәннен кемінде 5 балл (бейіндік пәндер) жинау қажет.', 'Порог в национальные вузы - 65, в другие вузы - 50. Минимум по 5 баллов по каждому профильному предмету.', 'verified', 'a0000001-0000-0000-0000-000000000001'),
('10000001-0000-0000-0000-000000000002', '2026-2027', 'e0000001-0000-0000-0000-000000000002', NULL, 'Математика', 'Математика', 'Информатика', 'Информатика', 50, 65, false, 'Барлық IT мамандықтары бойынша бейіндік жұп: Математика + Информатика.', 'По всем IT-специальностям профильная пара: Математика + Информатика.', 'verified', 'a0000001-0000-0000-0000-000000000001'),
('10000001-0000-0000-0000-000000000003', '2026-2027', 'e0000001-0000-0000-0000-000000000003', NULL, 'Биология', 'Биология', 'Химия', 'Химия', 70, 70, false, 'Медициналық бағыттар үшін республикалық шекті балл кемінде 70. Арнайы психометриялық тесттен өткені туралы рұқсат қажет.', 'Для медицины порог не менее 70 баллов. Требуется успешная сдача психометрического теста.', 'verified', 'a0000001-0000-0000-0000-000000000001'),
('10000001-0000-0000-0000-000000000004', '2026-2027', 'e0000001-0000-0000-0000-000000000004', NULL, 'Дүниежүзі тарихы', 'Всемирная история', 'Құқық негіздері', 'Основы права', 50, 75, false, 'Құқықтану бағыты үшін бейіндік пәндер: Дүниежүзі тарихы және Адам. Қоғам. Құқық (Құқық негіздері).', 'Для права профильные предметы: Всемирная история и Основы права.', 'verified', 'a0000001-0000-0000-0000-000000000001'),
('10000001-0000-0000-0000-000000000005', '2026-2027', 'e0000001-0000-0000-0000-000000000007', NULL, 'Математика', 'Математика', 'Физика', 'Физика', 75, 75, false, 'Педагогикалық бағыттар үшін шекті балл кемінде 75. Арнайы педагогикалық емтиханнан өту міндетті.', 'Порог на педагогические специальности - не менее 75 баллов. Обязателен специальный педагогический экзамен.', 'verified', 'a0000001-0000-0000-0000-000000000001'),
('10000001-0000-0000-0000-000000000006', '2026-2027', 'e0000001-0000-0000-0000-000000000008', NULL, 'Математика', 'Математика', 'География', 'География', 50, 50, false, 'Менеджмент және басқару бойынша бейіндік жұп: Математика + География. Шекті балл - 50.', 'Профильная пара: Математика + География. Пороговый балл - 50.', 'verified', 'a0000001-0000-0000-0000-000000000015'),
('10000001-0000-0000-0000-000000000007', '2026-2027', 'e0000001-0000-0000-0000-000000000009', NULL, 'Математика', 'Математика', 'География', 'География', 50, 50, false, 'Қаржы және аудит бойынша бейіндік жұп: Математика + География. Шекті балл - 50.', 'Профильная пара: Математика + География. Пороговый балл - 50.', 'verified', 'a0000001-0000-0000-0000-000000000015'),
('10000001-0000-0000-0000-000000000008', '2026-2027', 'e0000001-0000-0000-0000-000000000010', NULL, 'Математика', 'Математика', 'Информатика', 'Информатика', 50, 65, false, 'Телекоммуникациялар бойынша бейіндік жұп: Математика + Информатика.', 'Профильная пара: Математика + Информатика.', 'verified', 'a0000001-0000-0000-0000-000000000015');
