INSERT INTO grants (id, slug, title_kz, title_ru, provider_kz, provider_ru, grant_type, location_scope, education_level, direction_id, coverage_type, coverage_details_kz, coverage_details_ru, eligibility_criteria_kz, eligibility_criteria_ru, required_documents_kz, required_documents_ru, selection_process_kz, selection_process_ru, application_url, academic_year, status, source_id) VALUES
('40000001-0000-0000-0000-000000000001', 'astana-akimat-grant', 'Астана қаласы әкімінің гранты (303 орын)', 'Грант акима города Астаны (303 места)', 'Астана қаласының әкімдігі және Білім басқармасы', 'Акимат и Управление образования города Астаны', 'akimat_astana', 'astana', 'bachelor', NULL, 'full_tuition', 'Оқу ақысы 100% төленеді + мемлекеттік шәкіртақы тағайындалады.', '100% покрытие стоимости обучения + ежемесячная государственная стипендия.', 'Астана қаласында тұрақты тіркеуі бар, ҰБТ шекті балын жинаған талапкерлер. 2026 жылы 303 грант бөлінген: көлік қызметі (ЕҰУ), мектепке дейінгі білім (ЕАГИ), педагогика және IT (AIU, Esil). Оқу бітірген соң Астана ұйымдарында 3 жыл жұмыс істеу міндетті.', 'Абитуриенты с постоянной пропиской в Астане, набравшие пороговый балл ЕНТ. На цикл выделено 303 гранта (транспорт в ЕНУ, педагогика в AIU и Esil). Обязательство отработки 3 года в организациях столицы.', '{"Жеке куәлік көшірмесі", "ҰБТ сертификаты", "Аттестат", "Астанада тұрақты тіркеуі туралы мекенжай анықтамасы", "Флюорография / 075-У"}', '{"Копия удостоверения личности", "Сертификат ЕНТ", "Аттестат", "Справка с места жительства в Астане", "Медсправка 075-У"}', 'Конкурс ҰБТ балы бойынша университеттің қабылдау комиссиясында өтеді (тамыздың 5-10 аралығында).', 'Конкурс по баллам ЕНТ через приемные комиссии вузов столицы с 5 по 10 августа.', 'https://www.gov.kz/memleket/entities/astana-bilim', '2026-2027', 'verified', 'a0000001-0000-0000-0000-000000000002'),
('40000001-0000-0000-0000-000000000002', 'state-general-grant', 'ҚР Жалпы Мемлекеттік Білім беру гранты', 'Общий государственный образовательный грант РК', 'ҚР Ғылым және жоғары білім министрлігі', 'Министерство науки и высшего образования РК', 'national', 'kazakhstan', 'bachelor', NULL, 'full_tuition', 'Толық 4 жылдық оқу ақысы және ай сайынғы шәкіртақы.', 'Полная стоимость обучения на бакалавриате и ежемесячная стипендия.', 'ҰБТ шекті балынан өткен барлық мектеп бітірушілері. 4 білім беру бағдарламалары тобын таңдау мүмкіндігі.', 'Все выпускники, преодолевшие порог ЕНТ. Возможность указать до 4 групп образовательных программ.', '{"Аттестат", "ҰБТ сертификаты", "075-У анықтамасы", "Жеке куәлік"}', '{"Аттестат", "Сертификат ЕНТ", "Медсправка 075-У", "Удостоверение личности"}', 'Республикалық конкурстық комиссия шешімі, өткен жылғы баллдар мен квоталарды есепке алу.', 'Республиканский конкурс через eGov.kz в июле.', 'https://testcenter.kz', '2026-2027', 'verified', 'a0000001-0000-0000-0000-000000000001'),
('40000001-0000-0000-0000-000000000003', 'qazaqstan-khalqyna-grant', '"Қазақстан халқына" Қорының Білім Гранты', 'Образовательный грант фонда "Қазақстан халқына"', '"Қазақстан халқына" қоғамдық қоры', 'Общественный фонд "Қазақстан халқына"', 'charitable', 'kazakhstan', 'bachelor', NULL, 'full_tuition', 'Толық оқу ақысы + күнтізбелік жыл бойы шәкіртақы.', '100% стоимости обучения + ежемесячная стипендия.', 'Әлеуметтік осал санаттағы талапкерлер: жетім балалар, 1/2 топ мүгедектігі барлар, көп балалы және аз қамтылған отбасы балалары. ҰБТ шекті балы міндетті.', 'Социально уязвимые категории выпускников, преодолевшие порог ЕНТ, но не получившие госгрант.', '{"Санатты растайтын құжаттар", "ҰБТ сертификаты", "Аттестат"}', '{"Документы подтверждающие категорию", "Сертификат ЕНТ", "Аттестат"}', 'Қор порталы арқылы өтініш қабылдау (тамыз айы).', 'Подача заявления через платформу фонда в августе.', 'https://qazaqstanhalqyna.kz', '2026-2027', 'verified', 'a0000001-0000-0000-0000-000000000007'),
('40000001-0000-0000-0000-000000000004', 'aitu-rector-grant', 'AITU Ректор гранты және оқу жеңілдіктері', 'Ректорский грант и скидки Astana IT University', 'Astana IT University', 'Astana IT University', 'rector', 'astana', 'bachelor', 'c0000001-0000-0000-0000-000000000001', 'partial_tuition', '100%, 50% және 25% оқу ақысына жеңілдіктер.', '100%, 50% и 25% скидки на оплату обучения.', 'Республикалық және халықаралық олимпиада жүлдегерлері (Дарын, Жәутіков), ҰБТ-дан 125+ балл жинаған талапкерлер.', 'Призеры республиканских олимпиад (Дарын, Жаутыковская), обладатели 125+ баллов ЕНТ.', '{"Олимпиада дипломдары", "ҰБТ сертификаты", "Портфолио"}', '{"Дипломы олимпиад", "Сертификат ЕНТ", "Портфолио"}', 'Университет ішкі комиссиясының шешімі бойынша маусым-тамыз аралығында қаралады.', 'Рассматривается внутренней комиссией университета.', 'https://astanait.edu.kz', '2026-2027', 'verified', 'a0000001-0000-0000-0000-000000000003'),
('40000001-0000-0000-0000-000000000005', 'kazenergy-educational-grant', 'KAZENERGY білім беру гранты (NCOC және KPO)', 'Образовательный грант KAZENERGY (спонсорство NCOC и KPO)', 'KAZENERGY Қауымдастығы / NCOC / KPO', 'Ассоциация KAZENERGY / NCOC / KPO', 'corporate', 'kazakhstan', 'bachelor', 'c0000001-0000-0000-0000-000000000002', 'full_tuition', '100% оқу ақысын өтеу техникалық және мұнай-газ мамандықтары бойынша.', '100% возмещение стоимости обучения по техническим и нефтегазовым специальностям.', 'Қазақстанның аккредиттелген ЖОО-ларында оқитын немесе түсетін азаматтар. Үздік оқу үлгерімі, әлеуметтік осал санаттарға басымдық беріледі.', 'Граждане РК, обучающиеся на техническом профиле, с высоким средним баллом GPA.', '{"Үлгерім транскрипті немесе аттестат", "ҰБТ сертификаты", "Отбасы құрамы туралы анықтама"}', '{"Транскрипт или аттестат", "Сертификат ЕНТ", "Справка о доходах семьи"}', 'KAZENERGY ресми порталында онлайн конкурс (шілде-тамыз).', 'Конкурсный отбор через портал ассоциации KAZENERGY в июле-августе.', 'https://kazenergy.com', '2026-2027', 'verified', 'a0000001-0000-0000-0000-000000000010'),
('40000001-0000-0000-0000-000000000006', 'nazarbayev-university-grant', '«Назарбаев Университеті» Мемлекеттік білім гранты', 'Государственный образовательный грант Назарбаев Университета', 'ҚР Үкіметі және Назарбаев Университеті', 'Правительство РК и Назарбаев Университет', 'national', 'astana', 'bachelor', NULL, 'full_tuition', 'Толық 100% оқу ақысы + ай сайынғы шәкіртақы + медициналық сақтандыру.', '100% покрытие стоимости обучения + стипендия + медицинская страховка.', 'NUET ішкі емтиханы немесе SAT/ACT + IELTS (кемінде 6.0/6.5) нәтижесі бойынша қабылданған ҚР азаматтары. ҰБТ балы қажет емес.', 'Граждане РК, успешно сдавшие вступительный экзамен NUET или SAT/ACT + IELTS и поступившие в NU. Поступление без ЕНТ.', '{"Аттестат немесе транскрипт", "IELTS / TOEFL сертификаты", "SAT / ACT (бар болса)", "Жеке куәлік", "Эссе және ұсыным хат"}', '{"Аттестат или транскрипт", "Сертификат IELTS / TOEFL", "SAT / ACT (при наличии)", "Удостоверение личности", "Мотивационное эссе"}', 'Назарбаев Университетінің қабылдау порталы арқылы онлайн өтінім беру және кезеңді іріктеу.', 'Многоэтапный отбор через admissions.nu.edu.kz.', 'https://nu.edu.kz/admissions', '2026-2027', 'verified', 'a0000001-0000-0000-0000-000000000015');
INSERT INTO opportunities (id, slug, title_kz, title_ru, provider_kz, provider_ru, opportunity_type, description_kz, description_ru, target_audience_kz, target_audience_ru, age_grade_restrictions, cost_type, benefits_kz, benefits_ru, duration_kz, duration_ru, location_mode, application_url, application_requirements_kz, application_requirements_ru, status, source_id) VALUES
('50000001-0000-0000-0000-000000000001', 'tech-orda-voucher', 'Tech Orda — Тегін IT-ваучерлер бағдарламасы', 'Tech Orda — Программа бесплатных ИТ-ваучеров', 'Astana Hub және ҚР ЦДИАӨМ', 'Astana Hub и МЦРИАП РК', 'course', 'Қазақстанның аккредиттелген IT-мектептерінде веб-бағдарламалау, Data Science және киберқауіпсіздікті тегін оқуға арналған 600 000 теңгелік ваучер.', 'Ваучеры до 600 000 ₸ на бесплатное обучение веб-разработке, машинному обучению и кибербезопасности в ведущих школах.', '18-35 жас аралығындағы азаматтар және 11-сынып бітірушілері.', 'Граждане РК от 18 до 35 лет, выпускники школ и студенты.', '18-35 жас', 'free', 'Тегін кәсіби білім, сертификат, жұмысқа орналасуға көмек.', 'Бесплатное образование, сертификат, содействие в трудоустройстве.', '6-12 ай', '6-12 месяцев', 'hybrid', 'https://astanahub.com/en/tech-orda/', 'Astana Hub порталында онлайн тіркелу, мектептің іріктеу тестінен өту.', 'Регистрация на портале Astana Hub, прохождение тестирования.', 'verified', 'a0000001-0000-0000-0000-000000000008'),
('50000001-0000-0000-0000-000000000002', 'daryn-informatics-olympiad', 'Информатикадан Республикалық "Дарын" олимпиадасы', 'Республиканская олимпиада школьников по информатике', 'Республикалық "Дарын" ғылыми-практикалық орталығы', 'РНПЦ "Дарын" Минпросвещения РК', 'olympiad', 'Мектеп оқушылары арасындағы ең беделді бағдарламалау жарысы. Жүлдегерлер ҰБТ-сыз грант алу немесе басым құқыққа ие болады.', 'Главное республиканское соревнование школьников по спортивному программированию. Призеры получают приоритетное право на гранты.', '9, 10, 11-сынып оқушылары.', 'Учащиеся 9, 10, 11 классов школ Астаны и регионов.', '9-11 сынып', 'free', 'ЖОО-ға басым құқықпен түсу, диплом, бағалы сыйлықтар.', 'Преимущественное право на образовательные гранты вузов, медали.', 'Қалалық және республикалық кезеңдер', 'Городской и республиканский этапы', 'in_person_astana', 'https://daryn.kz', 'Мектеп және аудандық кезеңдерден өту.', 'Успешное участие в школьном и районном турах.', 'verified', 'a0000001-0000-0000-0000-000000000001'),
('50000001-0000-0000-0000-000000000003', 'astana-hub-startup-garage', 'Astana Hub "Startup Garage" Инкубациясы', 'Программа инкубации Startup Garage в Astana Hub', 'Astana Hub халықаралық технопаркі', 'Международный технопарк IT-стартапов Astana Hub', 'mentorship', 'Мектеп және университет оқушыларына арналған өз IT стартапын нөлден бастап құру, менторлық және инвестиция тарту бағдарламасы.', 'Интенсивная менторская программа для запуска технологического стартапа со школьной или студенческой скамьи.', 'Жобасы немесе IT идеясы бар оқушылар мен студенттер.', 'Школьники старших классов и студенты с проектами.', 'Шектеусіз', 'free', 'Тегін коворкинг, EXPO алаңы, трекерлік көмек, сарапшылар менторы.', 'Бесплатное рабочее пространство в EXPO, трекеры, менторы.', '3 ай', '3 месяца', 'in_person_astana', 'https://astanahub.com', 'Өтінім беру және жоба идеясын таныстыру (питчинг).', 'Подача заявки и видео-презентация идеи.', 'verified', 'a0000001-0000-0000-0000-000000000008'),
('50000001-0000-0000-0000-000000000004', 'tomorrow-school-alem', 'Tomorrow School (alem.ai) — Жасанды интеллект және IT мектебі', 'Tomorrow School (alem.ai) — Бесплатная школа ИИ и программирования', 'Tomorrow School & alem.ai', 'Tomorrow School и alem.ai (Astana Hub)', 'course', 'Астанадағы peer-to-peer әдістемесімен оқытатын инновациялық IT мектебі. Мұғалімсіз және бағалаусыз, тәжірибелік жобалар арқылы Go, Rust, JavaScript және AI модельдерін терең меңгеру.', 'Школа программирования мирового уровня без учителей и лекций. Практика на реальных проектах, командная работа и гарантированный вход в ИТ.', '18 жастан асқан мектеп бітірушілер және жастар.', 'Выпускники 11 классов и молодые специалисты от 18 лет.', '18+ жас', 'free', '100% тегін оқу, халықаралық портфолио, жетекші IT компанияларға жұмысқа орналасу мүмкіндігі.', '100% бесплатное обучение, круглосуточный кампус в EXPO, содействие в карьере.', '1.5 - 2 жыл', '1.5 - 2 года', 'in_person_astana', 'https://alem.school', 'Онлайн логикалық ойындардан өту және 4 апталық қарқынды бассейн (Piscine) іріктеуінен сүрінбей өту.', 'Прохождение логических онлайн-игр и 4-недельного интенсива (Piscine).', 'verified', 'a0000001-0000-0000-0000-000000000011'),
('50000001-0000-0000-0000-000000000005', 'joltap-astana-project', 'JOLTAP — Астана тұрғындарына арналған тегін цифрлық және кәсіби курстар', 'JOLTAP — Бесплатные цифровые и практические курсы для жителей Астаны', 'Астана қаласы әкімдігі және "Жаңа мүмкіндік" қоры', 'Акимат г. Астаны и фонд "Жаңа мүмкіндік"', 'course', 'Астана әкімдігінің модульдік қысқа курстары: SMM, Таргетинг, Графикалық дизайн, Мобилография, Веб-сайт әзірлеу, 1С Бухгалтерия және қолөнер мамандықтары.', 'Бесплатные краткосрочные курсы для жителей столицы по востребованным профессиям на рынке труда.', 'Астана қаласының тұрғындары (18-50 жас).', 'Жители города Астаны от 18 до 50 лет.', '18-50 жас', 'free', 'Тегін модульдік білім, сертификат, ресми жұмыспен қамтуға және микрогранттарға бағыттау.', 'Бесплатное обучение, официальный сертификат, трудоустройство.', '2 - 4 апта', '2 - 4 недели', 'in_person_astana', 'https://joltap.kz', 'Астана қаласындағы модульдік пункттерге немесе ресми сайтқа өтініш беру.', 'Подача заявки в пунктах JOLTAP или на сайте проекта.', 'verified', 'a0000001-0000-0000-0000-000000000012');
